pluralize.code:
fn pluralize(s: string) -> string {
    if s.ends_with("h") {
        return s + "es";
    }
    if s.ends_with("s") {
        return s + "es";
    }
    if s.ends_with("x") {
        return s + "es";
    }
    if s.ends_with("y") {
        return s.slice(0, s.len - 1) + "ies";
    }
    return s + "s";
}

reverse.code:
fn reverse(s: string) -> string {
    return s.reverse();
}

